const initialState = {
    counter: 1,
};

export const counterReducer = (state = initialState, action) => {
    switch (action.type) {
        case 'INCREASE_COUNTER':
            return state + 1;
        case 'DECREASE_COUNTER':
            return state - 1;
        default:
            return state;
    }
}
